import json,re,sys
from pathlib import Path
from profile_window import command
p=Path(sys.argv[1]);b=(p/'memory.bin').read_bytes();m=json.loads((p/'anchor.json').read_text());syms={n:int(v,16) for n,v in re.findall(r'^(\w+)\s+00:([0-9A-F]+)$',(p/'slave.lst').read_text(encoding='latin-1'),re.M)};base=m.get('slave_base',m['memory_base']+b.index(b'4DFRAMTW')-syms['raster_frame_marker']);names=['raster_staged_count','raster_fallback_count','raster_fallback_pc']+(['raster_present_early'] if 'raster_present_early' in syms else []);command(f'gdb delete\ntbreak *{m["game_base"]+0x7500:#x}\ncontinue');r=command('gdb '+'\n'.join(f'p /u *(unsigned int*){base+syms[n]:#x}' for n in names));vals=[int(v) for v in re.findall(r'^\$\d+ = (\d+)',r,re.M)];assert len(vals)==len(names);report=dict(zip(names,vals));report['last_fallback_game_offset']=hex(report['raster_fallback_pc']-m['game_base']) if report['raster_fallback_pc'] else None;(p/'stage-check.json').write_text(json.dumps(report,indent=2)+'\n');print(report)
